examples.code:
const animal = { eats: true, walk() { return "walking"; } };
const dog = Object.create(animal);
dog.barks = true;

console.log(dog.eats, dog.walk());
console.log(Object.getPrototypeOf(dog) === animal);
console.log(Object.hasOwn(dog, "eats"), "eats" in dog);

const arr = [];
console.log(Object.getPrototypeOf(arr) === Array.prototype);
console.log(Object.getPrototypeOf(Array.prototype) === Object.prototype);
console.log(Object.getPrototypeOf(Object.prototype));

for (const key in dog) console.log("key:", key);

topics.description:
A **constructor function** is a normal function, named with a capital letter by convention, designed to be called with `new`.

```js
function Person(name, age) {
  this.name = name;
  this.age = age;
}
Person.prototype.greet = function () {
  return `Hi, I am ${this.name}`;
};
const p = new Person("Asha", 25);
```

### What `new` does
1. Creates a new empty object.
2. Links its prototype to `Person.prototype`.
3. Calls `Person` with `this` set to the new object.
4. Returns the object (unless the constructor returns another object).

### Instance vs prototype members
- Properties set on `this` belong to **each instance** (own properties).
- Methods placed on `Person.prototype` are **shared**, so only one copy exists.

### Checks
```js
p instanceof Person;        // true
p.constructor === Person;   // true
```

### Forgetting `new`
Without `new`, `this` is `undefined` (strict) or `window`, so properties leak to the global object. Guard with `if (!new.target) throw ...`, or use a class, which throws automatically.

### Factory functions
A function that returns a new object without `new`; works well with closures for private data:
```js
const createUser = (name) => ({ name, hello: () => `hi ${name}` });
```

### Built-in constructors
`Date`, `Map`, `Set`, `Promise`, `Error` are used with `new`. Avoid `new String()`, `new Number()` and `new Boolean()` - they create objects, not primitives.

examples.code:
function Person(name, age) {
  this.name = name;
  this.age = age;
}
Person.prototype.greet = function () {
  return `Hi, I am ${this.name} (${this.age})`;
};

const p1 = new Person("Asha", 25);
const p2 = new Person("Ravi", 30);
console.log(p1.greet(), p2.greet());
console.log(p1.greet === p2.greet);            // shared method
console.log(p1 instanceof Person, p1.constructor === Person);
console.log(Object.keys(p1));

function myNew(Ctor, ...args) {
  const obj = Object.create(Ctor.prototype);
  const result = Ctor.apply(obj, args);
  return result instanceof Object ? result : obj;
}
console.log(myNew(Person, "Meera", 22).greet());

class Account {
  balance = 0;
  static count = 0;

  constructor(owner) {
    this.owner = owner;
    Account.count++;
  }
  deposit(amount) {
    if (amount <= 0) throw new RangeError("Amount must be positive");
    this.balance += amount;
    return this;                       // chaining
  }
  get summary() {
    return `${this.owner}: ${this.balance}`;
  }
  static compare(a, b) {
    return a.balance - b.balance;
  }
}

const acc = new Account("Asha").deposit(100).deposit(50);
console.log(acc.summary, Account.count);
console.log(typeof Account, acc instanceof Account);
try { Account("x"); } catch (e) { console.log(e.name); }
console.log([new Account("B").deposit(10), acc].sort(Account.compare).map((a) => a.owner));

topics.description:
`extends` makes one class inherit from another.

```js
class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }
}
class Dog extends Animal {
  constructor(name, breed) {
    super(name);            // must come before using this
    this.breed = breed;
  }
  speak() {                 // override
    return `${super.speak()} - woof!`;
  }
}
```

### Rules
- In a derived constructor you **must call `super()` before using `this`**, otherwise a `ReferenceError` is thrown. If you omit the constructor, one is created for you.
- `super.method()` calls the parent version of a method.
- Static methods are inherited too.
- `instanceof` works along the chain: `dog instanceof Animal` is `true`.

### Under the hood
`Dog.prototype`'s prototype is `Animal.prototype`, and `Dog`'s own prototype is `Animal` (so statics are inherited).

### Extending built-ins
`class MyArray extends Array {}` and `class ValidationError extends Error {}` are common and useful.

### Composition over inheritance
Deep inheritance trees become rigid. Prefer **composition**: build behaviour from small functions or objects ("has-a") and mix them in:

```js
const canFly = (o) => ({ ...o, fly: () => `${o.name} flies` });
```
Use inheritance for clear "is-a" relationships with shallow depth.

### Polymorphism
Different subclasses implement the same method differently, and callers use them through the common interface.

examples.code:
class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }
  static kingdom() { return "Animalia"; }
}
class Dog extends Animal {
  constructor(name, breed) {
    super(name);
    this.breed = breed;
  }
  speak() { return `${super.speak()} - woof!`; }
}
const d = new Dog("Bruno", "Labrador");
console.log(d.speak());
console.log(d instanceof Dog, d instanceof Animal, Dog.kingdom());
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype);

class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}
try { throw new ValidationError("Email is invalid", "email"); }
catch (e) { console.log(e.name, e.field, e instanceof Error); }

topics.description:
### Private fields and methods (ES2022)
Names starting with `#` are truly private - they can be accessed only inside the class body. Access from outside is a **syntax error**, not just `undefined`.

```js
class Wallet {
  #balance = 0;                    // private field
  #log(msg) { /* private method */ }
  static #instances = 0;           // private static
  deposit(n) { this.#balance += n; }
  get balance() { return this.#balance; }
}
```
- Check existence with `#balance in obj`.
- They are not inherited as visible names and are not copied by spread or `JSON.stringify`.

### Static members and blocks
```js
class Config {
  static defaults = { theme: "dark" };
  static getDefault(key) { return Config.defaults[key]; }
  static { /* static initialisation block (ES2022) */ }
}
```
Statics live on the class, not on instances.

### Getters and setters
Accessors look like properties but run code. Use them for validation, derived values and read-only properties:
```js
set age(v) { if (v < 0) throw new RangeError("age"); this.#age = v; }
```

### Old convention
Before `#`, developers used a leading underscore (`_balance`) - a hint only; it was not enforced.

### Singleton and factories
Statics are used for factories (`User.from(json)`), counters and singletons.

### Encapsulation benefit
Callers use a stable public API and cannot corrupt internal state.

examples.code:
class Wallet {
  #balance = 0;
  static #created = 0;

  constructor(owner) {
    this.owner = owner;
    Wallet.#created++;
  }
  deposit(amount) {
    if (amount <= 0) throw new RangeError("Deposit must be positive");
    this.#balance += amount;
    return this;
  }
  get balance() { return this.#balance; }
  set limit(v) { if (v < 0) throw new RangeError("negative"); this._limit = v; }
  static get created() { return Wallet.#created; }
  static isWallet(o) { return #balance in o; }
}

const w = new Wallet("Asha").deposit(500);
console.log(w.balance, Wallet.created, Wallet.isWallet(w), Wallet.isWallet({}));
console.log(JSON.stringify(w), Object.keys(w));
console.log(w.hasOwnProperty("#balance"));
